#!/usr/bin/env node
import {
  lstat,
  mkdir,
  readFile,
  readdir,
  readlink,
  symlink,
  unlink,
  writeFile,
} from "node:fs/promises";
import path from "node:path";
import { ROOT, loadOrganization } from "./lib/governance.mjs";

const writeMode = process.argv.includes("--write");
const organization = await loadOrganization();
const workerRoles = organization.roles.filter(
  ({ id }) => id !== "orchestrator",
);
const generatedMarker =
  "Generated by tools/generate-agent-adapters.mjs; do not edit.";

function canonicalPrompt(role) {
  return `Read root/nearest AGENTS.md and .agents/roles/${role.id}.md. Follow the canonical authority, budgets, stop conditions and required output.`;
}

function codexAdapter(role) {
  return `# Generated by tools/generate-agent-adapters.mjs; do not edit.\nname = ${JSON.stringify(role.id)}\ndescription = ${JSON.stringify(role.description)}\nsandbox_mode = ${JSON.stringify(role.mode === "scoped-write" ? "workspace-write" : "read-only")}\ndeveloper_instructions = ${JSON.stringify(canonicalPrompt(role))}\n`;
}

function claudeAdapter(role) {
  const tools = ["Read", "Glob", "Grep"];
  if (role.capabilities.includes("write")) tools.push("Edit", "Write");
  if (role.mode === "scoped-write" && role.capabilities.includes("shell"))
    tools.push("Bash");
  return `---\nname: ${role.id}\ndescription: ${role.description}\ntools: ${tools.join(", ")}\nmaxTurns: ${role.maxTurns}\n---\n\n<!-- Generated by tools/generate-agent-adapters.mjs; do not edit. -->\n\n${canonicalPrompt(role)}\n`;
}

function geminiAdapter(role) {
  const tools = ["read_file", "list_directory", "grep_search"];
  if (role.mode === "scoped-write" && role.capabilities.includes("shell"))
    tools.push("run_shell_command");
  if (role.capabilities.includes("write")) tools.push("replace", "write_file");
  return `---\nname: ${role.id}\ndescription: ${role.description}\nkind: local\ntools:\n${tools.map((tool) => `  - ${tool}`).join("\n")}\nmax_turns: ${role.maxTurns}\n---\n\n<!-- Generated by tools/generate-agent-adapters.mjs; do not edit. -->\n\n${canonicalPrompt(role)}\n`;
}

const providers = [
  { directory: ".codex/agents", extension: ".toml", render: codexAdapter },
  { directory: ".claude/agents", extension: ".md", render: claudeAdapter },
  { directory: ".gemini/agents", extension: ".md", render: geminiAdapter },
];

const failures = [];
let pruned = 0;
for (const provider of providers) {
  const directory = path.join(ROOT, provider.directory);
  if (writeMode) await mkdir(directory, { recursive: true });
  const expectedNames = new Set(
    workerRoles.map(({ id }) => `${id}${provider.extension}`),
  );
  let actualNames = [];
  try {
    actualNames = (await readdir(directory)).filter((name) =>
      name.endsWith(provider.extension),
    );
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
    if (!writeMode) failures.push(`${provider.directory} is missing`);
  }
  for (const extra of actualNames.filter((name) => !expectedNames.has(name))) {
    const relativePath = `${provider.directory}/${extra}`;
    const file = path.join(directory, extra);
    const content = await readFile(file, "utf8");
    if (writeMode && content.includes(generatedMarker)) {
      await unlink(file);
      pruned += 1;
    } else {
      failures.push(
        `${relativePath} is not in canonical organization${writeMode ? " and is not generated; refusing to remove it" : ""}`,
      );
    }
  }

  for (const role of workerRoles) {
    const file = path.join(directory, `${role.id}${provider.extension}`);
    const expected = provider.render(role);
    if (writeMode) {
      await writeFile(file, expected);
      continue;
    }
    let actual = null;
    try {
      actual = await readFile(file, "utf8");
    } catch {
      failures.push(
        `${provider.directory}/${role.id}${provider.extension} is missing`,
      );
      continue;
    }
    if (actual !== expected)
      failures.push(
        `${provider.directory}/${role.id}${provider.extension} has drifted; run npm run adapters:generate`,
      );
  }
}

const skillLinks = [
  { link: ".claude/skills", target: "../.agents/skills" },
  { link: "backend/api/.claude/skills", target: "../.agents/skills" },
  { link: "backend/ai/.claude/skills", target: "../.agents/skills" },
];
for (const item of skillLinks) {
  const link = path.join(ROOT, item.link);
  let existing = null;
  try {
    existing = await lstat(link);
  } catch (error) {
    if (error.code !== "ENOENT") throw error;
  }
  if (existing) {
    if (!existing.isSymbolicLink())
      failures.push(`${item.link} must be a symlink to ${item.target}`);
    else if ((await readlink(link)) !== item.target)
      failures.push(
        `${item.link} points to ${await readlink(link)}, expected ${item.target}`,
      );
  } else if (writeMode) {
    await mkdir(path.dirname(link), { recursive: true });
    await symlink(item.target, link);
  } else failures.push(`${item.link} is missing`);
}

if (failures.length > 0) {
  process.stderr.write(`${failures.join("\n")}\n`);
  process.exit(1);
}

process.stdout.write(
  writeMode
    ? `Generated Codex, Claude and Gemini adapters; pruned ${pruned} generated extra(s).\n`
    : "Agent adapters match canonical organization.\n",
);
